export const TRAINING_LESSONS_BY_AUDIENCE: Record<TrainingAudience, TrainingLessonDefinition[]> = { owner: OWNER_TRAINING_LESSONS, staff: STAFF_TRAINING_LESSONS };

export function normalizeCurriculumLocale(language?: string | null): TrainingLocale { const value = (language || 'en').toLowerCase().split('-')[0] as TrainingLocale; return ['en','el','de','es','tr'].includes(value) ? value : 'en'; }
export function trainingTerm(key: string, language?: string | null) { const locale = normalizeCurriculumLocale(language); return TEXT[key]?.[locale] || TEXT[key]?.en || key; }
function interpolate(template: string, values: Record<string,string>) { return Object.entries(values).reduce((value,[key,replacement]) => value.replaceAll(`{{${key}}}`, replacement), template); }
export function getLocalizedTrainingLesson(definition: TrainingLessonDefinition, language?: string | null) { const locale = normalizeCurriculumLocale(language); const template = TEMPLATES[locale]; const title = trainingTerm(definition.titleKey, locale); const page = trainingTerm(definition.pageKey, locale); const action = trainingTerm(definition.actionKey, locale); const result = trainingTerm(definition.resultKey, locale); return { ...definition, title, page, action, result, objective: interpolate(template.objective,{title}), steps: [interpolate(template.open,{page}), interpolate(template.choose,{action}), template.verify, interpolate(template.confirm,{result})], checklist: definition.fieldKeys.map((key) => trainingTerm(key, locale)), tipText: template.tips[definition.tip] }; }
export function getTrainingLessons(audience: TrainingAudience, language?: string | null) { return TRAINING_LESSONS_BY_AUDIENCE[audience].map((lesson) => getLocalizedTrainingLesson(lesson, language)); }
export function getTrainingLessonsForGuide(audience: TrainingAudience, guideSlug: TrainingGuideSlug, language?: string | null) { return getTrainingLessons(audience, language).filter((lesson) => lesson.guideSlug === guideSlug); }
export function getTrainingCompletionPercent(completed: string[], audience: TrainingAudience) { const total = TRAINING_LESSONS_BY_AUDIENCE[audience].length; return total ? Math.round((TRAINING_LESSONS_BY_AUDIENCE[audience].filter((lesson) => completed.includes(lesson.id)).length / total) * 100) : 0; }